// Vault KEY blob IPNS (stores ECIES-wrapped rootFolderKey) — NOT the root folder IPNS
const VAULT_KEY_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-key-ipns-v1');

/**
 * Derive the vault root IPNS name from user's secp256k1 private key.
 * Matches the derivation in @cipherbox/crypto deriveVaultIpnsKeypair.
 *
 * Path: secp256k1 privateKey -> HKDF-SHA256 -> 32-byte Ed25519 seed
 *       -> Ed25519 public key -> IPNS name (k51...)
 */
async function deriveVaultIpnsName(userPrivateKey) {
  // 1. HKDF-SHA256 to derive 32-byte Ed25519 seed
  const keyMaterial = await crypto.subtle.importKey(
    'raw', userPrivateKey, 'HKDF', false, ['deriveBits']
  );
