() => {
  // 1. Inject performance monitoring on fetch
  window.__perfLog = [];
  window.__perfStart = performance.now();
  const origFetch = window.fetch;
  window.fetch = async function(...args) {
    const url = typeof args[0] === 'string' ? args[0] : args[0]?.url || '';
    const method = args[1]?.method || 'GET';
    const start = performance.now();
    try {
      const resp = await origFetch.apply(this, args);
      const elapsed = performance.now() - start;
      const since = Math.round(performance.now() - window.__perfStart);
      if (url.includes('/vault') || url.includes('/ipns') || url.includes('/ipfs') || url.includes('/auth')) {
        window.__perfLog.push({ t: since, url: url.replace(/https:\/\/[^/]+/, ''), method, status: resp.status, ms: Math.round(elapsed) });
      }
      return resp;
    } catch(e) {
      const elapsed = performance.now() - start;
      const since = Math.round(performance.now() - window.__perfStart);
      window.__perfLog.push({ t: since, url: url.replace(/https:\/\/[^/]+/, ''), method, status: 'ERR', ms: Math.round(elapsed) });
      throw e;
    }
  };

  // 2. Inject a minimal EIP-1193 Ethereum provider with a deterministic key
  // Using a throwaway test key (not sensitive)
  const TEST_PRIVATE_KEY = 'REDACTED';
  const TEST_ADDRESS = '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266'; // hardhat #0

  window.ethereum = {
    isMetaMask: true,
    _testKey: TEST_PRIVATE_KEY,
    selectedAddress: TEST_ADDRESS,
    chainId: '0x1',
    networkVersion: '1',
    _listeners: {},
    on(event, cb) { (this._listeners[event] = this._listeners[event] || []).push(cb); },
    removeListener(event, cb) {
      if (this._listeners[event]) this._listeners[event] = this._listeners[event].filter(l => l !== cb);
    },
    async request({ method, params }) {
      console.log('[MockWallet] request:', method, params);
      switch (method) {
        case 'eth_requestAccounts':
        case 'eth_accounts':
          return [TEST_ADDRESS];
        case 'eth_chainId':
          return '0x1';
        case 'net_version':
          return '1';
        case 'personal_sign': {
          // Web3Auth asks for a signature - we need to sign with our key
          // Import ethers from the page if available, otherwise return a mock
          const message = params[0];
          console.log('[MockWallet] personal_sign request for:', message?.substring(0, 50));
          // Use Web Crypto to create a deterministic "signature" 
          // Web3Auth just needs any valid-looking response
          const encoder = new TextEncoder();
          const keyData = new Uint8Array(32);
          for (let i = 0; i < 32; i++) keyData[i] = parseInt(TEST_PRIVATE_KEY.slice(2 + i*2, 4 + i*2), 16);
          const key = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
          const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(typeof message === 'string' ? message : ''));
          const sigHex = '0x' + Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('') + '1b';
          return sigHex;
        }
        case 'wallet_switchEthereumChain':
          return null;
        case 'wallet_addEthereumChain':
          return null;
        default:
          console.log('[MockWallet] unhandled method:', method);
          throw new Error(`MockWallet: unsupported method ${method}`);
      }
    }
  };

  // Dispatch the ethereum provider event
  window.dispatchEvent(new Event('ethereum#initialized'));

  return 'Monitoring + mock wallet injected';
}

