  2→import { installMockWallet } from '@johanneskares/wallet-mock';
  3→import { privateKeyToAccount } from 'viem/accounts';
  4→import { mainnet } from 'viem/chains';
  5→import { custom } from 'viem';
  6→import { LoginPage } from '../page-objects/login.page';
  7→
  8→/**
  9→ * Local-only transport for the mock wallet.
 10→ * Avoids network calls to default mainnet RPC which hang in CI.
 11→ */
 12→const localTransport = custom({
 13→  async request({ method }) {
 14→    switch (method) {
 15→      case 'eth_chainId':
 16→        return '0x1';
 17→      case 'net_version':
 18→        return '1';
 19→      case 'eth_blockNumber':
 20→        return '0x0';
 21→      case 'eth_getBalance':
 22→        return '0x0';
 23→      default:
 24→        throw new Error(`Mock transport: unhandled method ${method}`);
 25→    }
 26→  },
 27→});
