 29→/**
 30→ * Wallet Login E2E Tests (TC09-TC12)
 31→ *
 32→ * Tests wallet login flows using @johanneskares/wallet-mock which provides
 33→ * an EIP-6963 mock provider. The mock wallet auto-announces itself and
 34→ * wagmi's injected() connector auto-discovers it.
 35→ *
 36→ * The mock uses viem's privateKeyToAccount for real ECDSA signatures,
 37→ * so the backend SIWE verifyMessage() performs real crypto verification.
 38→ *
 39→ * Test account: Hardhat account #0 (well-known test key, no real funds)
 40→ */
 41→
 42→// Hardhat account #0 private key (well-known, deterministic, no real funds)
 43→const HARDHAT_ACCOUNT_0_KEY =
 44→  '0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80' as const;
 45→
 46→// ============================================
 47→// TC09: Wallet login happy path (with mock wallet)
 48→// ============================================
 49→
 50→test.describe('TC09: Wallet login happy path (with mock wallet)', () => {
 51→  let loginPage: LoginPage;
 52→
 53→  test.beforeEach(async ({ page }) => {
 54→    // Install mock wallet BEFORE navigating to the page
 55→    const account = privateKeyToAccount(HARDHAT_ACCOUNT_0_KEY);
 56→    await installMockWallet({
 57→      page,
 58→      account,
 59→      defaultChain: mainnet,
 60→      transports: { [mainnet.id]: localTransport },
 61→    });
 62→
 63→    loginPage = new LoginPage(page);
 64→    await loginPage.goto();
 65→  });
 66→
 67→  test('wallet button is visible and enabled', async () => {
 68→    // Wait for Core Kit init to complete (wallet button becomes enabled)
 69→    await expect(async () => {
 70→      expect(await loginPage.isWalletLoginButtonVisible()).toBe(true);
 71→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
 72→    }).toPass({ timeout: 15000 });
 73→  });
 74→
 75→  test('clicking wallet shows mock wallet in connector list', async () => {
 76→    // Wait for wallet button to be ready
 77→    await expect(async () => {
 78→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
 79→    }).toPass({ timeout: 15000 });
 80→
 81→    // Click wallet button to show connectors
 82→    await loginPage.clickWalletLogin();
 83→
 84→    // Connector list should be visible
 85→    expect(await loginPage.isWalletConnectorListVisible()).toBe(true);
 86→
 87→    // Mock Wallet should appear in the connector list
 88→    const connectors = await loginPage.getWalletConnectors();
 89→    expect(connectors).toContain('Mock Wallet');
 90→  });
 91→
 92→  test('selecting mock wallet initiates SIWE flow', async ({ page }) => {
 93→    test.setTimeout(30000);
 94→
 95→    // Wait for wallet button to be ready
 96→    await expect(async () => {
 97→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
 98→    }).toPass({ timeout: 15000 });
 99→
100→    // Click wallet, then select Mock Wallet
101→    await loginPage.clickWalletLogin();
102→    await loginPage.selectWalletConnector('Mock Wallet');
103→
104→    // The mock wallet auto-approves connectAsync and signMessage.
105→    // The SIWE flow will:
106→    // 1. Connect wallet (auto-approved)
107→    // 2. Fetch nonce from backend
108→    // 3. Create SIWE message
109→    // 4. Sign message (auto-approved)
110→    // 5. Verify on backend
111→    // 6. Continue with Core Kit login
112→    //
113→    // Wait for either:
114→    // - Redirect to /files (full success, requires running backend + Core Kit devnet)
115→    // - An error message (expected if Core Kit/backend not fully available)
116→    // - A status change indicating SIWE flow progressed
117→    const result = await Promise.race([
118→      page
119→        .waitForURL('**/files', { timeout: 20000 })
120→        .then(() => 'redirected' as const)
121→        .catch(() => null),
122→      loginPage
123→        .getWalletError()
124→        .then((err) => (err ? ('error' as const) : null))
125→        .catch(() => null),
126→      // Wait a bit for the flow to progress
127→      page.waitForTimeout(5000).then(async () => {
128→        // Check if we got a status update (SIWE flow progressing)
129→        const status = await loginPage.getWalletStatus();
130→        const error = await loginPage.getWalletError();
131→        if (error) return 'error' as const;
132→        if (status) return 'in-progress' as const;
133→        return 'timeout' as const;
134→      }),
135→    ]);
136→
137→    if (result === 'redirected') {
138→      // Full SIWE flow completed - user is logged in
139→      await expect(page).toHaveURL(/.*files/);
140→    } else {
141→      // SIWE flow started but may have failed at backend/Core Kit step.
142→      // This is acceptable - the important thing is:
143→      // 1. Mock wallet was discovered (we clicked it)
144→      // 2. Connect was initiated (no "no wallet" error)
145→      // 3. Either SIWE signing happened or nonce fetch was attempted
146→      // Log the result for debugging
147→      console.log(`SIWE flow result: ${result}`);
148→
149→      // The flow should NOT show "No wallet detected" since we installed mock
150→      const error = await loginPage.getWalletError();
151→      if (error) {
152→        expect(error).not.toContain('No wallet detected');
153→        expect(error).not.toContain('no wallet');
154→      }
155→    }
156→  });
157→});
