160→// TC10: Wallet login cancel
161→// ============================================
162→
163→test.describe('TC10: Wallet login cancel', () => {
164→  let loginPage: LoginPage;
165→
166→  test.beforeEach(async ({ page }) => {
167→    const account = privateKeyToAccount(HARDHAT_ACCOUNT_0_KEY);
168→    await installMockWallet({
169→      page,
170→      account,
171→      defaultChain: mainnet,
172→      transports: { [mainnet.id]: localTransport },
173→    });
174→
175→    loginPage = new LoginPage(page);
176→    await loginPage.goto();
177→  });
178→
179→  test('cancelling wallet connector list returns to initial state', async () => {
180→    // Wait for wallet button to be ready
181→    await expect(async () => {
182→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
183→    }).toPass({ timeout: 15000 });
184→
185→    // Click wallet to show connector list
186→    await loginPage.clickWalletLogin();
187→    expect(await loginPage.isWalletConnectorListVisible()).toBe(true);
188→
189→    // Click cancel
190→    await loginPage.cancelWalletLogin();
191→
192→    // Connector list should be hidden
193→    expect(await loginPage.isWalletConnectorListVisible()).toBe(false);
194→
195→    // Wallet button should be visible and enabled again
