201→// ============================================
202→// TC11: Wallet login no wallet detected
203→// ============================================
204→
205→test.describe('TC11: Wallet login no wallet detected', () => {
206→  let loginPage: LoginPage;
207→
208→  test.beforeEach(async ({ page }) => {
209→    // Do NOT install mock wallet - test no-wallet state
210→    loginPage = new LoginPage(page);
211→    await loginPage.goto();
212→  });
213→
214→  test('no wallet message shown when no providers detected', async () => {
215→    // Wait for wallet button to be ready
216→    await expect(async () => {
217→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
218→    }).toPass({ timeout: 15000 });
219→
220→    // Click wallet button
221→    await loginPage.clickWalletLogin();
222→
223→    // Either the no-providers message is shown, or zero connector options appear.
224→    // wagmi may report phantom "injected" connectors (browser built-in)
225→    // so we need to handle both cases.
226→    const isNoProviders = await loginPage.isNoWalletProvidersVisible();
227→    const connectors = await loginPage.getWalletConnectors().catch(() => [] as string[]);
228→
229→    if (!isNoProviders && connectors.length > 0) {
230→      // wagmi reported phantom connectors (e.g., browser built-in injected)
231→      // This is acceptable - the point is Mock Wallet should NOT be there
232→      expect(connectors).not.toContain('Mock Wallet');
233→    } else {
234→      // No providers message or empty connector list
235→      expect(isNoProviders || connectors.length === 0).toBe(true);
236→    }
237→
238→    // Cancel should work regardless
239→    await loginPage.cancelWalletLogin();
240→    expect(await loginPage.isWalletConnectorListVisible()).toBe(false);
241→  });
242→});
