244→// ============================================
245→// TC12: Wallet login error handling
246→// ============================================
247→
248→test.describe('TC12: Wallet login error handling', () => {
249→  let loginPage: LoginPage;
250→
251→  test.beforeEach(async ({ page }) => {
252→    const account = privateKeyToAccount(HARDHAT_ACCOUNT_0_KEY);
253→    await installMockWallet({
254→      page,
255→      account,
256→      defaultChain: mainnet,
257→      transports: { [mainnet.id]: localTransport },
258→    });
259→
260→    loginPage = new LoginPage(page);
261→    await loginPage.goto();
262→  });
263→
264→  test('error during SIWE flow shows error message and allows retry', async ({ page }) => {
265→    test.setTimeout(30000);
266→
267→    // Wait for wallet button to be ready
268→    await expect(async () => {
269→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
270→    }).toPass({ timeout: 15000 });
271→
272→    // Intercept the nonce endpoint to simulate a server error
273→    await page.route('**/auth/identity/wallet/nonce', (route) =>
274→      route.fulfill({
275→        status: 500,
276→        contentType: 'application/json',
277→        body: JSON.stringify({ message: 'Internal Server Error' }),
278→      })
279→    );
280→
281→    // Click wallet, then select Mock Wallet
282→    await loginPage.clickWalletLogin();
283→    await loginPage.selectWalletConnector('Mock Wallet');
284→
285→    // Wait for error to appear (nonce fetch fails -> error displayed)
286→    const errorLocator = page.locator('.wallet-login-wrapper .login-error');
287→    await expect(errorLocator).toBeVisible({ timeout: 10000 });
288→
289→    // Error should be shown
290→    const error = await loginPage.getWalletError();
291→    expect(error).toBeTruthy();
292→
293→    // Remove the route interception for retry
294→    await page.unroute('**/auth/identity/wallet/nonce');
295→
296→    // Wallet button should return to idle and enabled state
297→    await expect(async () => {
298→      expect(await loginPage.isWalletLoginButtonVisible()).toBe(true);
299→      expect(await loginPage.isWalletLoginButtonEnabled()).toBe(true);
300→    }).toPass({ timeout: 10000 });
301→  });
302→});
