130→/**
131→ * Navigate a wallet test account's page to the shared files view.
132→ * Navigates away first to force a component remount and fresh data fetch.
133→ */
134→export async function navigateToShared(account: WalletTestAccount): Promise<void> {
135→  const currentUrl = account.page.url();
136→  if (currentUrl.includes('/shared')) {
137→    await account.page.evaluate(() => {
138→      window.location.hash = '#/files';
139→    });
140→    await account.page.waitForURL('**/files', { timeout: 30000 });
141→  }
142→  await account.page.evaluate(() => {
143→    window.location.hash = '#/shared';
144→  });
145→  await account.page.waitForURL('**/shared', { timeout: 30000 });
146→}
