148→/**
149→ * Navigate a wallet test account's page to their own files.
150→ * Navigates away first to force a component remount and fresh data fetch.
151→ */
152→export async function navigateToFiles(account: WalletTestAccount): Promise<void> {
153→  const currentUrl = account.page.url();
154→  if (currentUrl.includes('/files')) {
155→    await account.page.evaluate(() => {
156→      window.location.hash = '#/shared';
157→    });
158→    await account.page.waitForURL('**/shared', { timeout: 30000 });
159→  }
160→  await account.page.evaluate(() => {
161→    window.location.hash = '#/files';
162→  });
163→  await account.page.waitForURL('**/files', { timeout: 30000 });
164→}
