 12→  constructor(private readonly configService: ConfigService) {
 13→    const rawOrigins = this.configService.get<string>('CORS_ALLOWED_ORIGINS');
 14→    this.allowedDomains = rawOrigins
 15→      ? rawOrigins
 16→          .split(',')
 17→          .map((o) => o.trim())
 18→          .filter((o) => !o.includes('*'))
 19→          .map((o) => {
 20→            try {
 21→              const url = new URL(o);
 22→              return url.host;
 23→            } catch {
 24→              return o;
 25→            }
 26→          })
 27→      : ['localhost:5173', 'localhost:4173', 'localhost'];
 28→  }
 29→
 30→  /**
 31→   * Generate a cryptographically random nonce for SIWE.
 32→   * Returns 32 hex characters (16 random bytes).
 33→   * Exceeds EIP-4361 minimum of 8 alphanumeric characters.
 34→   */
 35→  generateNonce(): string {
 36→    return randomBytes(16).toString('hex');
 37→  }
 38→
 39→  /**
 40→   * Verify a SIWE message and signature (EOA only, no RPC needed).
 41→   * Validates the domain against CORS_ALLOWED_ORIGINS.
 42→   * Returns the verified wallet address (EIP-55 checksummed).
 43→   *
 44→   * @throws UnauthorizedException if message is invalid or signature doesn't match
