import { chromium } from '@playwright/test';
import { installMockWallet } from '@johanneskares/wallet-mock';
import { privateKeyToAccount } from 'viem/accounts';
import { mainnet } from 'viem/chains';
import { custom } from 'viem';

const STAGING_URL = 'https://app-staging.cipherbox.cc';

const account = privateKeyToAccount('0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80');

const localTransport = custom({
  async request({ method }) {
    switch (method) {
      case 'eth_chainId': return '0x1';
      case 'net_version': return '1';
      case 'eth_blockNumber': return '0x0';
      case 'eth_getBalance': return '0x0';
      default: throw new Error(`Mock transport: unhandled ${method}`);
    }
  },
});

async function run() {
  console.log('=== Staging Vault Login Path — E2E Performance Baseline ===');
  console.log(`Date: ${new Date().toISOString()}`);
  console.log(`Wallet address: ${account.address}`);
  console.log('');

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  // Install mock wallet BEFORE navigation
  await installMockWallet({
    page,
    account,
    defaultChain: mainnet,
    transports: { [mainnet.id]: localTransport },
  });

  // Inject perf monitoring
  await page.addInitScript(() => {
    window.__perfLog = [];
    window.__perfStart = performance.now();
    const origFetch = window.fetch;
    window.fetch = async function(...args) {
      const url = typeof args[0] === 'string' ? args[0] : args[0]?.url || '';
      const method = args[1]?.method || 'GET';
      const start = performance.now();
      try {
        const resp = await origFetch.apply(this, args);
        const elapsed = performance.now() - start;
        const since = Math.round(performance.now() - window.__perfStart);
        if (url.includes('/vault') || url.includes('/ipns') || url.includes('/ipfs') || url.includes('/auth')) {
          window.__perfLog.push({ t: since, url: url.replace(/https:\/\/[^/]+/, ''), method, status: resp.status, ms: Math.round(elapsed) });
        }
        return resp;
      } catch(e) {
        const elapsed = performance.now() - start;
        const since = Math.round(performance.now() - window.__perfStart);
        window.__perfLog.push({ t: since, url: url.replace(/https:\/\/[^/]+/, ''), method, status: 'ERR', ms: Math.round(elapsed) });
        throw e;
      }
    };
  });

  // Navigate
  console.log('--- Navigating to staging ---');
  const navStart = Date.now();
  await page.goto(STAGING_URL);
  await page.getByText('initializing...').first().waitFor({ state: 'hidden' });
  console.log(`Page loaded: ${Date.now() - navStart}ms`);

  // Wait for wallet button to be enabled
  const walletButton = page.locator('[data-testid="wallet-login-button"]');
  await walletButton.waitFor({ state: 'visible', timeout: 20_000 });
  await page.waitForFunction(
    () => {
      const btn = document.querySelector('[data-testid="wallet-login-button"]');
      return btn && !btn.disabled;
    },
    { timeout: 20_000 }
  );
  console.log(`Core Kit initialized: ${Date.now() - navStart}ms`);
  console.log('');

  // Reset perf timer right before login
  await page.evaluate(() => {
    window.__perfLog = [];
    window.__perfStart = performance.now();
  });

  // Click wallet button
  console.log('--- Starting wallet login ---');
  const loginStart = Date.now();
  await walletButton.click();

  // Select Mock Wallet
  const connectorList = page.locator('.wallet-connector-list');
  await connectorList.waitFor({ state: 'visible', timeout: 5_000 });
  const mockWalletOption = page.locator('.wallet-connector-option', { hasText: 'Mock Wallet' });
  await mockWalletOption.click();
  console.log(`Wallet selected: ${Date.now() - loginStart}ms`);

  // Wait for outcome
  try {
    const result = await Promise.race([
      page.waitForURL('**/files', { timeout: 60_000 }).then(() => 'success'),
      page.locator('[data-testid="device-waiting"]')
        .waitFor({ state: 'visible', timeout: 60_000 })
        .then(() => 'requiredShare'),
    ]);
    console.log(`Login outcome: ${result} (${Date.now() - loginStart}ms)`);

    if (result === 'success') {
      // Wait for vault + SDK init (file list or empty state)
      await Promise.race([
        page.locator('.file-list[role="grid"]').waitFor({ state: 'visible', timeout: 30_000 }),
        page.locator('[data-testid="empty-state"]').waitFor({ state: 'visible', timeout: 30_000 }),
      ]);
      console.log(`Vault ready: ${Date.now() - loginStart}ms`);
    }
  } catch (e) {
    console.log(`Login failed/timed out: ${e.message}`);
    // Capture screenshot
    await page.screenshot({ path: '/tmp/staging-perf-fail.png' });
  }

  // Collect perf logs
  console.log('');
  console.log('--- API Call Waterfall ---');
  const perfLog = await page.evaluate(() => window.__perfLog);
  if (perfLog && perfLog.length > 0) {
    console.log('T(ms)  | Method | Status | Duration | URL');
    console.log('-------|--------|--------|----------|----');
    for (const entry of perfLog) {
      console.log(
        `${String(entry.t).padStart(6)} | ${entry.method.padEnd(6)} | ${String(entry.status).padEnd(6)} | ${String(entry.ms + 'ms').padEnd(8)} | ${entry.url}`
      );
    }
  } else {
    console.log('(no API calls captured)');
  }

  // Check console for errors
  console.log('');
  const consoleErrors = await page.evaluate(() => {
    return window.__consoleErrors || [];
  });

  await browser.close();
  console.log('');
  console.log('=== Done ===');
}

run().catch(e => {
  console.error('Fatal:', e);
  process.exit(1);
});

