 39→export function useAuth() {
 40→  const navigate = useNavigate();
 41→  const {
 42→    isLoggedIn: coreKitLoggedIn,
 43→    isInitialized: coreKitInitialized,
 44→    isRequiredShare,
 45→    loginWithGoogle: coreKitLoginGoogle,
 46→    loginWithEmailOtp: coreKitLoginEmail,
 47→    loginWithWallet: coreKitLoginWallet,
 48→    getVaultKeypair,
 49→    getPublicKeyHex,
 50→    logout: coreKitLogout,
 51→  } = useCoreKitAuth();
 52→  const { syncStatus } = useCoreKit();
 53→  const {
 54→    accessToken,
 55→    isAuthenticated,
 56→    lastAuthMethod,
 57→    userEmail,
 58→    setAccessToken,
 59→    setAuthenticated,
 60→    setLastAuthMethod,
 61→    setUserEmail,
 62→    setVaultKeypair,
 63→  } = useAuthStore();
 64→
 65→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 66→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 67→  const restoringRef = useRef(false);
 68→
 69→  // Stable refs for functions used in the session restoration effect.
 70→  // This prevents the effect from re-firing when function references change.
 71→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 72→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 73→
 74→  // Pending auth state for REQUIRED_SHARE flow.
 75→  // Stored in Zustand (not useState) so the state is shared across all
 76→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 77→  // via its own useAuth() call.
 78→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 79→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 80→
 81→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 82→
 83→  // Get vault store actions
 84→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 85→
 86→  /**
 87→   * Initialize vault for new users or load existing vault keys.
 88→   * Called after successful backend authentication.
 89→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 90→   */
 91→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 92→    // Get user's secp256k1 keypair from Core Kit TSS export
 93→    const userKeypair = await getVaultKeypair();
 94→
 95→    if (!userKeypair) {
 96→      throw new Error('Failed to get vault keypair from Core Kit');
 97→    }
 98→
 99→    // Store keypair in auth store for crypto operations
100→    setVaultKeypair(userKeypair);
101→
102→    // Isolate getVault() so only its 404 triggers new-user initialization.
103→    // Downstream errors (IPNS resolve, IPFS fetch) must not be misclassified.
104→    let existingVault: Awaited<ReturnType<typeof vaultApi.getVault>> | null = null;
105→    try {
106→      existingVault = await vaultApi.getVault();
107→    } catch (error) {
108→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
109→      if (!is404) {
110→        console.error('[useAuth] Failed to load vault:', error);
111→        throw error;
112→      }
113→    }
114→
115→    if (existingVault) {
116→      // Store TEE keys if available
117→      if (existingVault.teeKeys) {
118→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
119→      }
120→
121→      // Read rootFolderKey from dedicated vault key IPNS (separate from root folder IPNS)
122→      const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
123→
124→      const resolved = await resolveIpnsRecord(vaultKeyKeypair.ipnsName);
125→      if (!resolved) throw new Error('Vault key IPNS name not found');
126→
127→      const blobBytes = await fetchFromIpfs(resolved.cid);
128→
129→      if (detectBlobVersion(blobBytes) !== 2) {
130→        throw new Error('Vault key blob is not v2 format');
131→      }
132→
133→      const encKey = deserializeVaultBlobV2(blobBytes);
134→      const rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
135→
136→      // Root folder IPNS keypair is the original vault derivation
137→      const rootIpnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
138→
139→      setVaultKeys({
140→        rootFolderKey,
141→        rootIpnsKeypair,
142→        rootIpnsName: existingVault.rootIpnsName,
143→        vaultId: existingVault.id,
144→      });
145→    } else {
146→      // New user -- initialize vault with separate key blob + folder metadata
147→      console.log('[Auth] New user -- initializing vault');
148→      const newVault = await initializeVault(userKeypair.privateKey);
149→      const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
150→
151→      // Derive vault key IPNS keypair (separate from root folder IPNS)
152→      const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
153→      const vaultKeyIpnsName = vaultKeyKeypair.ipnsName;
154→
155→      // 1. Publish v2 key blob to vault key IPNS (rootFolderKey storage — key only, no metadata)
156→      const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);
157→      const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey);
158→
159→      const keyBlobUpload = await addToIpfs(new Blob([v2Blob as BlobPart]));
160→      const keyPublishResult = await createAndPublishIpnsRecord({
161→        ipnsPrivateKey: vaultKeyKeypair.privateKey,
162→        ipnsName: vaultKeyIpnsName,
163→        metadataCid: keyBlobUpload.cid,
164→        sequenceNumber: 0n,
165→        expectedSequenceNumber: undefined,
166→      });
167→      if (!keyPublishResult.success) {
168→        throw new Error('Failed to publish vault key blob to IPNS');
169→      }
170→
171→      // 2. Publish folder metadata using v1 encrypted envelope format on IPFS ({iv, data});
172→      //    FolderMetadata.version remains 'v2' (metadata schema version).
173→      const emptyMetadata: FolderMetadata = { version: 'v2', children: [] };
174→      const encrypted = await encryptFolderMetadata(emptyMetadata, newVault.rootFolderKey);
175→      const metadataBlob = new Blob([JSON.stringify(encrypted)], { type: 'application/json' });
176→      const metadataUpload = await addToIpfs(metadataBlob);
177→      const folderPublishResult = await createAndPublishIpnsRecord({
178→        ipnsPrivateKey: newVault.rootIpnsKeypair.privateKey,
179→        ipnsName: rootIpnsName,
180→        metadataCid: metadataUpload.cid,
181→        sequenceNumber: 0n,
182→        expectedSequenceNumber: undefined,
183→      });
184→      if (!folderPublishResult.success) {
185→        throw new Error('Failed to publish initial root folder metadata');
186→      }
187→
188→      // 3. Register vault with API (no crypto fields -- IPFS-only)
189→      const storedVault = await vaultApi.initVault({
190→        ownerPublicKey: bytesToHex(userKeypair.publicKey),
191→        rootIpnsName,
192→      });
193→
194→      if (storedVault.teeKeys) {
195→        useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
196→      }
197→
198→      setVaultKeys({
199→        rootFolderKey: newVault.rootFolderKey,
200→        rootIpnsKeypair: newVault.rootIpnsKeypair,
201→        rootIpnsName,
202→        vaultId: storedVault.id,
203→        isNewVault: true,
204→      });
205→    }
206→
207→    // Initialize SDK client with decrypted vault keys
208→    const vaultState = useVaultStore.getState();
209→    const authState = useAuthStore.getState();
210→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
211→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
212→      const getAccessToken = async () => {
213→        const state = useAuthStore.getState();
214→        return state.accessToken || '';
215→      };
216→
217→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
218→
219→      const sdkClient = initSdkClient({
220→        apiUrl,
221→        getAccessToken,
222→        vaultKeypair: {
223→          publicKey: userKeypair.publicKey,
224→          privateKey: userKeypair.privateKey,
225→        },
226→        rootIpnsName: vaultState.rootIpnsName,
227→        rootFolderKey: vaultState.rootFolderKey,
228→        teeKeys: authState.teeKeys ?? undefined,
229→        shareCallbacks: {
230→          getCoveringShares: async (folderIpnsName: string) => {
231→            const { findCoveringShares } = await import('../services/share.service');
232→            const folders = useFolderStore.getState().folders;
233→            // Find the folder ID from IPNS name for ancestor traversal
234→            const folderId =
235→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
236→            return findCoveringShares(folderIpnsName, folders, folderId);
237→          },
238→          addShareKeys: async (shareId, keys) => {
239→            const { addShareKeys } = await import('../services/share.service');
240→            await addShareKeys(shareId, keys);
241→          },
242→        },
243→      });
244→
245→      // Subscribe folder store to SDK events
246→      useFolderStore.getState().subscribeToSdk(sdkClient);
247→
248→      // Subscribe bin store to SDK events
249→      useBinStore.getState().subscribeToSdk(sdkClient);
250→    }
251→
252→    // Non-blocking device registry initialization (fire-and-forget)
253→    // Placed after vault load so registry failures never block login
254→    void (async () => {
255→      try {
256→        const deviceKeypair = await getOrCreateDeviceIdentity({
257→          mode: 'persisted',
258→          vaultPrivateKey: userKeypair.privateKey,
259→        });
260→        const deviceInfo = detectDeviceInfo();
261→        const result = await initializeOrSyncRegistry({
262→          userPrivateKey: userKeypair.privateKey,
263→          userPublicKey: userKeypair.publicKey,
264→          deviceKeypair,
265→          deviceInfo: { ...deviceInfo, ipHash: '' },
266→        });
267→        if (result) {
268→          useDeviceRegistryStore
269→            .getState()
270→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
271→        }
272→      } catch (error) {
273→        console.error('[Auth] Device registry init failed (non-blocking):', error);
274→      }
275→    })();
276→
277→    // Non-blocking bin initialization (fire-and-forget)
278→    // After old service creates/loads bin, also load into SDK for deleteToBin support
279→    void (async () => {
280→      try {
281→        await initializeBin({
282→          userPrivateKey: userKeypair.privateKey,
283→          userPublicKey: userKeypair.publicKey,
284→        });
285→        // Now load bin into SDK (old service ensures bin IPNS record exists)
286→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
287→        if (hasSdkClient()) {
288→          await getSdkClient().loadBin();
289→        }
290→      } catch (error) {
291→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
292→      }
293→    })();
294→
295→    // Non-blocking: fetch retention config from API
296→    void (async () => {
297→      try {
298→        const config = await vaultControllerGetConfig();
299→        if (config.recycleBinRetentionDays != null) {
300→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
301→        }
302→      } catch (error) {
303→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
304→      }
305→    })();
306→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
307→
308→  /**
309→   * Complete backend authentication after Core Kit login.
310→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
311→   * to the backend with loginType 'corekit'. The backend verifies it against
312→   * its own JWKS since CipherBox is the identity provider.
313→   */
314→  const completeBackendAuth = useCallback(
315→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
316→      // 1. Get real publicKey from Core Kit TSS export
317→      const publicKey = await getPublicKeyHex();
318→      if (!publicKey) {
319→        throw new Error('Failed to get publicKey from Core Kit');
320→      }
321→
322→      // publicKey available for debugging via DevTools if needed
323→
324→      // 2. Authenticate with CipherBox backend
325→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
326→      const response = await authApi.login({
327→        idToken: cipherboxJwt,
328→        publicKey,
329→        loginType: 'corekit',
330→      });
331→
332→      // 3. Store access token (refresh token in HTTP-only cookie)
333→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
334→      // are fully initialized to prevent Login.tsx from redirecting to /files
335→      // before the SDK client is ready for file operations.
336→      setAccessToken(response.accessToken);
337→
338→      // 4. Remember auth method for UX
339→      setLastAuthMethod(authMethod);
340→
341→      // 5. Initialize or load vault + SDK client
342→      await initializeOrLoadVault();
343→
344→      // 6. Now that vault keys are loaded and SDK is initialized,
345→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
346→      setAuthenticated();
347→    },
348→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
349→  );
350→
351→  /**
352→   * Complete the login flow after REQUIRED_SHARE is resolved.
353→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
354→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
355→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
356→   */
357→  const completeRequiredShare = useCallback(async (): Promise<void> => {
358→    // Read directly from Zustand store to get fresh values — this callback
359→    // may be called from useDeviceApproval's useAuth() instance, so we
360→    // can't rely on closure-captured selector values.
361→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
362→
363→    if (!jwt || !method) {
364→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
365→    }
366→
367→    // Core Kit should now be LOGGED_IN after inputFactorKey()
368→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
369→    await completeBackendAuth(method, jwt);
370→
371→    // NOW sync Core Kit React state to LOGGED_IN.
372→    // We deliberately delayed this from inputFactorKey() to prevent the session
373→    // restoration effect from firing before backend auth completed.
374→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
375→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
376→    syncStatus();
377→
378→    // Clear pending state
379→    setPendingAuth(null, null);
380→
381→    // Navigate to files
382→    navigate('/files');
383→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
384→
385→  /**
386→   * Login with Google OAuth token.
387→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
388→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
389→   */
390→  const loginWithGoogle = useCallback(
391→    async (googleIdToken: string): Promise<void> => {
392→      if (isLoggingIn) return;
393→      setIsLoggingIn(true);
394→      try {
395→        // 1. Core Kit login via CipherBox identity provider
396→        const {
397→          cipherboxJwt,
398→          email,
399→          userId,
400→          status: coreKitStatus,
401→        } = await coreKitLoginGoogle(googleIdToken);
402→
403→        if (coreKitStatus === 'required_share') {
404→          // MFA enabled but device factor missing.
405→          // Store pending auth info for later completion after factor input.
406→          setPendingAuth(cipherboxJwt, 'google');
407→
408→          // Obtain temporary backend access token so the new device can
409→          // call bulletin board API endpoints (device-approval/*).
410→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
411→          // state and we can't export the TSS key yet.
412→          const tempLoginResponse = await authApi.login({
413→            idToken: cipherboxJwt,
414→            publicKey: `pending-core-kit-${userId}`,
415→            loginType: 'corekit',
416→          });
417→          setAccessToken(tempLoginResponse.accessToken);
418→
419→          if (email) {
420→            setUserEmail(email);
421→          }
422→
423→          // Do NOT call completeBackendAuth() or navigate('/files')
424→          // The component tree will see isRequiredShare === true and
425→          // render recovery/approval UI.
426→          return;
427→        }
428→
429→        // Normal path: Core Kit logged in, proceed as before
430→        // 2. Complete backend auth + vault init
431→        await completeBackendAuth('google', cipherboxJwt);
432→
433→        // 3. Store email for UI display (returned from identity endpoint)
434→        if (email) {
435→          setUserEmail(email);
436→        }
437→
438→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
439→      } catch (error) {
440→        console.error('[useAuth] Google login failed:', error);
441→        throw error;
442→      } finally {
443→        setIsLoggingIn(false);
444→      }
445→    },
446→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
447→  );
448→
449→  /**
450→   * Login with Email OTP.
451→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
452→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
453→   */
454→  const loginWithEmail = useCallback(
455→    async (email: string, otp: string): Promise<void> => {
456→      if (isLoggingIn) return;
457→      setIsLoggingIn(true);
458→      try {
459→        // 1. Core Kit login via CipherBox identity provider
460→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
461→
462→        if (coreKitStatus === 'required_share') {
463→          setPendingAuth(cipherboxJwt, 'email');
464→
465→          const tempLoginResponse = await authApi.login({
466→            idToken: cipherboxJwt,
467→            publicKey: `pending-core-kit-${userId}`,
468→            loginType: 'corekit',
469→          });
470→          setAccessToken(tempLoginResponse.accessToken);
471→          setUserEmail(email);
472→          return;
473→        }
474→
475→        // Normal path
476→        await completeBackendAuth('email', cipherboxJwt);
477→        setUserEmail(email);
478→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
479→      } catch (error) {
480→        console.error('[useAuth] Email login failed:', error);
481→        throw error;
482→      } finally {
483→        setIsLoggingIn(false);
484→      }
485→    },
486→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
487→  );
488→
489→  /**
490→   * Login with Wallet (SIWE).
491→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
492→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
493→   */
494→  const loginWithWallet = useCallback(
495→    async (cipherboxJwt: string, userId: string): Promise<void> => {
496→      if (isLoggingIn) return;
497→      setIsLoggingIn(true);
498→      try {
499→        // 1. Core Kit login via CipherBox identity provider
500→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
501→
502→        if (coreKitStatus === 'required_share') {
503→          setPendingAuth(cipherboxJwt, 'wallet');
504→
505→          const tempLoginResponse = await authApi.login({
506→            idToken: cipherboxJwt,
507→            publicKey: `pending-core-kit-${userId}`,
508→            loginType: 'corekit',
509→          });
510→          setAccessToken(tempLoginResponse.accessToken);
511→          return;
512→        }
513→
514→        // Normal path
515→        await completeBackendAuth('wallet', cipherboxJwt);
516→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
517→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
518→        // inside it may still be pending. An explicit navigate here would fire AFTER
519→        // vault init completes — by which point the user may have navigated away from
520→        // the login page, causing a disruptive late redirect.
521→      } catch (error) {
522→        console.error('[useAuth] Wallet login failed:', error);
523→        throw error;
524→      } finally {
525→        setIsLoggingIn(false);
526→      }
527→    },
528→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
529→  );
530→
531→  // Complete logout: Backend -> Core Kit -> Clear state
532→  const logout = useCallback(async () => {
533→    if (isLoggingOut) return;
534→
535→    setIsLoggingOut(true);
536→    try {
537→      // 1. Call backend logout (clears cookie)
538→      if (accessToken) {
539→        try {
540→          await authApi.logout();
541→        } catch {
542→          // Ignore errors -- we'll clear state anyway
543→        }
544→      }
545→
546→      // 2. Logout Core Kit (clears session from localStorage)
547→      await coreKitLogout();
548→
549→      // 3. Clear all user-scoped stores (centralized helper)
550→      clearAllUserStores();
551→
552→      // 4. Navigate to login
553→      navigate('/');
554→    } catch (error) {
555→      console.error('[useAuth] Logout failed:', error);
556→      // Still clear state even if backend fails
557→      clearAllUserStores();
558→      navigate('/');
559→    } finally {
560→      setIsLoggingOut(false);
561→    }
562→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
563→
564→  // Keep function refs up-to-date for use in session restoration effect.
565→  // Using refs prevents the effect from re-firing when function identities change.
566→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
567→  coreKitLogoutRef.current = coreKitLogout;
568→
569→  // Session restoration: if Core Kit restores a session from localStorage
570→  // on init, we have LOGGED_IN status without going through login flow.
571→  // Complete backend auth + vault loading.
572→  useEffect(() => {
573→    const restoreSession = async () => {
574→      // Only restore if Core Kit has a session but we don't have
575→      // a backend access token yet
576→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
577→        restoringRef.current = true;
578→        setIsLoggingIn(true);
579→        try {
580→          // Try to refresh using the HTTP-only cookie first
581→          const response = await authApi.refresh();
582→          setAccessToken(response.accessToken);
583→
584→          // Restore email from backend if available
585→          if (response.email) {
586→            setUserEmail(response.email);
587→          }
588→
589→          // Load vault keys from Core Kit keypair + initialize SDK
590→          await initializeOrLoadVaultRef.current?.();
591→
592→          // Mark as authenticated only after vault + SDK are ready
593→          setAuthenticated();
594→        } catch {
595→          // No valid backend session -- user needs to re-login
596→          // Core Kit session exists but backend cookie expired
597→          // Clear Core Kit session to avoid inconsistent state
598→          try {
599→            await coreKitLogoutRef.current?.();
600→          } catch {
601→            // Ignore logout errors during cleanup
602→          }
603→        } finally {
604→          restoringRef.current = false;
605→          setIsLoggingIn(false);
606→        }
607→      }
608→    };
609→    restoreSession();
610→  }, [
611→    coreKitLoggedIn,
612→    isAuthenticated,
613→    isLoggingIn,
614→    setAccessToken,
615→    setAuthenticated,
616→    setUserEmail,
617→  ]);
618→
619→  return {
620→    isLoading,
621→    isAuthenticated,
622→    isRequiredShare,
623→    lastAuthMethod,
624→    userEmail,
625→    pendingAuthMethod,
626→    loginWithGoogle,
627→    loginWithEmail,
628→    loginWithWallet,
629→    completeRequiredShare,
630→    logout,
631→  };
632→}
