  1→import axios, {
  2→  type AxiosInstance,
  3→  type AxiosRequestConfig,
  4→  type AxiosError,
  5→  type AxiosProgressEvent,
  6→  type CancelToken,
  7→} from 'axios';
  8→
  9→export type ApiClientConfig = {
 10→  /** Base URL for the CipherBox API (e.g., "http://localhost:3000") */
 11→  baseUrl: string;
 12→  /** Returns a valid access token. Consumer owns refresh logic. */
 13→  getAccessToken: () => Promise<string>;
 14→  /** Called on 401 response to obtain a new access token. If provided, the failed request is retried once with the new token. */
 15→  refreshAccessToken?: () => Promise<string>;
 16→  /** Send cookies cross-origin (needed for HTTP-only refresh token cookie in web). */
 17→  withCredentials?: boolean;
 18→  /** Called when token refresh fails (e.g., clear stores, redirect to login). */
 19→  onRefreshFailure?: () => void;
 20→  /** Extra headers sent with every request (e.g., throttle bypass for testing). */
 21→  defaultHeaders?: Record<string, string>;
 22→};
 23→
 24→/**
 25→ * Create a configured axios instance for CipherBox API calls.
 26→ * No Zustand, no import.meta.env -- all config injected by consumer.
 27→ *
 28→ * Includes:
 29→ * - Request interceptor: injects Bearer token from getAccessToken()
 30→ * - Response interceptor (optional): 401 refresh + retry when refreshAccessToken is provided
 31→ */
 32→export function createAxiosInstance(config: ApiClientConfig): AxiosInstance {
 33→  const instance = axios.create({
 34→    baseURL: config.baseUrl,
 35→    withCredentials: config.withCredentials ?? false,
 36→    headers: config.defaultHeaders,
 37→  });
 38→
 39→  // Request interceptor: inject auth token
 40→  instance.interceptors.request.use(async (reqConfig) => {
 41→    const token = await config.getAccessToken();
 42→    if (token) {
 43→      reqConfig.headers.set('Authorization', `Bearer ${token}`);
 44→    }
 45→    return reqConfig;
 46→  });
 47→
 48→  // Response interceptor: 401 refresh + retry (optional)
 49→  if (config.refreshAccessToken) {
 50→    const refreshFn = config.refreshAccessToken;
 51→    const onFailure = config.onRefreshFailure;
 52→    let refreshPromise: Promise<string> | null = null;
 53→
 54→    instance.interceptors.response.use(
 55→      (response) => response,
 56→      async (error: AxiosError) => {
 57→        const originalRequest = error.config as
 58→          | (AxiosRequestConfig & { _retry?: boolean })
 59→          | undefined;
 60→        if (!originalRequest) throw error;
 61→
 62→        // Don't retry refresh endpoint to avoid infinite loop
 63→        const isRefreshRequest = originalRequest.url?.includes('/auth/refresh');
 64→
 65→        if (error.response?.status === 401 && !originalRequest._retry && !isRefreshRequest) {
 66→          originalRequest._retry = true;
 67→
 68→          if (!refreshPromise) {
 69→            refreshPromise = refreshFn()
 70→              .catch((refreshError) => {
 71→                onFailure?.();
 72→                throw refreshError;
 73→              })
 74→              .finally(() => {
 75→                refreshPromise = null;
 76→              });
 77→          }
 78→
 79→          // All concurrent 401 handlers await the same promise
 80→          const token = await refreshPromise;
 81→          originalRequest.headers = originalRequest.headers ?? {};
 82→          originalRequest.headers['Authorization'] = `Bearer ${token}`;
 83→          return instance.request(originalRequest);
 84→        }
 85→
 86→        throw error;
 87→      }
 88→    );
 89→  }
 90→
 91→  return instance;
 92→}
 93→
 94→/**
 95→ * Singleton configuration for orval-generated code.
 96→ * The consumer must call setApiClientConfig() before using generated functions
 97→ * without passing _axiosInstance explicitly.
 98→ */
 99→let _config: ApiClientConfig | null = null;
100→let _instance: AxiosInstance | null = null;
101→
102→/**
103→ * Configure the module-level singleton used by orval-generated functions.
104→ *
105→ * @param config - API client configuration
106→ * @param instance - Optional pre-built axios instance. When provided,
107→ *   getCachedInstance() returns it directly instead of creating a new one.
108→ *   Use this to share a single instance between the singleton path and
109→ *   instance-scoped consumers (e.g., CipherBoxClient).
110→ */
111→export function setApiClientConfig(config: ApiClientConfig, instance?: AxiosInstance): void {
112→  _config = config;
113→  _instance = instance ?? null;
114→}
115→
116→export function getApiClientConfig(): ApiClientConfig {
117→  if (!_config) throw new Error('API client not configured. Call setApiClientConfig() first.');
118→  return _config;
119→}
120→
121→function getCachedInstance(): AxiosInstance {
122→  if (!_instance) {
123→    _instance = createAxiosInstance(getApiClientConfig());
124→  }
125→  return _instance;
126→}
127→
128→export const customInstance = async <T>(
129→  config: AxiosRequestConfig,
130→  options?: AxiosRequestConfig & { _axiosInstance?: AxiosInstance }
131→): Promise<T> => {
132→  const { _axiosInstance, ...restOptions } = options ?? {};
133→
134→  if (_axiosInstance) {
135→    // Instance-scoped path: the provided instance has its own interceptors for auth
136→    const response = await _axiosInstance.request<T>({
137→      ...config,
138→      ...restOptions,
139→      headers: {
140→        ...config.headers,
141→        ...restOptions.headers,
142→      },
143→    });
144→    return response.data;
145→  }
146→
147→  // Singleton path: uses getCachedInstance() which has its own request interceptor
148→  const instance = getCachedInstance();
149→
150→  const response = await instance.request<T>({
151→    ...config,
152→    ...restOptions,
153→    headers: {
154→      ...config.headers,
155→      ...restOptions.headers,
156→    },
157→  });
158→
159→  return response.data;
160→};
161→
162→export default customInstance;
163→
164→export type ErrorType<Error> = AxiosError<Error>;
165→export type BodyType<BodyData> = BodyData;
166→
167→// Re-export axios types that consumers need for IPFS upload (progress, cancel)
168→export type { AxiosInstance, AxiosProgressEvent, CancelToken };
169→export { default as axios } from 'axios';
