 12→import { User } from './entities/user.entity';
 13→import { AuthMethod } from './entities/auth-method.entity';
 14→import { RefreshToken } from './entities/refresh-token.entity';
 15→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
 16→import { IPFS_PROVIDER, IpfsProvider } from '../ipfs/providers/ipfs-provider.interface';
 17→import { JwtIssuerService } from './services/jwt-issuer.service';
 18→import { TokenService } from './services/token.service';
 19→import { SiweService } from './services/siwe.service';
 20→import { LoginDto, LoginServiceResult } from './dto/login.dto';
 21→import { RefreshServiceResult, LogoutResponseDto } from './dto/token.dto';
 22→
 23→@Injectable()
 24→export class AuthService {
 25→  private readonly logger = new Logger(AuthService.name);
 26→
 27→  constructor(
 28→    private jwtIssuerService: JwtIssuerService,
 29→    private tokenService: TokenService,
 30→    private siweService: SiweService,
 31→    @InjectRepository(User)
 32→    private userRepository: Repository<User>,
 33→    @InjectRepository(AuthMethod)
 34→    private authMethodRepository: Repository<AuthMethod>,
 35→    @InjectRepository(RefreshToken)
 36→    private refreshTokenRepository: Repository<RefreshToken>,
 37→    @InjectRepository(PinnedCid)
 38→    private pinnedCidRepository: Repository<PinnedCid>,
 39→    @Inject(IPFS_PROVIDER)
 40→    private ipfsProvider: IpfsProvider
 41→  ) {}
 42→
 43→  async login(loginDto: LoginDto): Promise<LoginServiceResult> {
 44→    // 1. Verify CipherBox-issued JWT.
 45→    // All auth methods now go through: CipherBox identity provider -> Core Kit loginWithJWT -> /auth/login.
 46→    const payload = await this.verifyCipherBoxJwt(loginDto.idToken);
 47→
 48→    // 2. Find or create user
 49→    let user = await this.userRepository.findOne({
 50→      where: { publicKey: loginDto.publicKey },
 51→    });
 52→
 53→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 54→    //
 55→    // Two scenarios need resolution:
 56→    //
 57→    // A) FIRST LOGIN completion: User was created with a placeholder publicKey
 58→    //    ('pending-core-kit-{verifierId}') during identity token issuance.
 59→    //    After Core Kit loginWithJWT, the client calls /auth/login with the
 60→    //    REAL publicKey. Find the placeholder user and update their publicKey.
 61→    //
 62→    // B) REQUIRED_SHARE temp auth: MFA is enabled but the new device can't
 63→    //    reconstruct the Core Kit key (missing device factor). The client
 64→    //    sends a placeholder publicKey to get a temp access token for the
 65→    //    device approval bulletin board. The user already has a REAL publicKey
 66→    //    from their first login, so we look them up by identity (authMethod
 67→    //    identifierHash) instead of by publicKey.
 68→    if (!user) {
 69→      const verifierId = payload.verifierId || payload.sub;
 70→
 71→      if (verifierId) {
 72→        // A) Check for user with placeholder publicKey (first login completion)
 73→        const placeholderUser = await this.userRepository.findOne({
 74→          where: { publicKey: `pending-core-kit-${verifierId}` },
 75→        });
 76→        if (placeholderUser) {
 77→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 78→          // Only update publicKey if the incoming key is a real one (not another placeholder)
 79→          if (!loginDto.publicKey.startsWith('pending-core-kit-')) {
 80→            placeholderUser.publicKey = loginDto.publicKey;
 81→            user = await this.userRepository.save(placeholderUser);
 82→          } else {
 83→            user = placeholderUser;
 84→          }
 85→        }
 86→      }
 87→
 88→      // B) REQUIRED_SHARE temp auth: user already completed first login (has real
 89→      //    publicKey), so no placeholder row exists. Look up directly by userId
 90→      //    from the JWT sub — works for all auth method types (email, Google, wallet).
 91→      if (!user && payload.sub && loginDto.publicKey.startsWith('pending-core-kit-')) {
 92→        const existingUser = await this.userRepository.findOne({
 93→          where: { id: payload.sub },
 94→        });
 95→        if (existingUser) {
 96→          this.logger.log(
 97→            `REQUIRED_SHARE temp auth: found existing user ${existingUser.id} by userId`
 98→          );
 99→          user = existingUser;
100→        }
101→      }
102→    }
103→
104→    const isNewUser = !user;
105→    if (!user) {
106→      user = await this.userRepository.save({
107→        publicKey: loginDto.publicKey,
108→      });
109→    }
110→
111→    // 3. Find or create auth method
112→    // The identity controller already created the auth method
113→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
114→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
115→    let authMethod: AuthMethod | null;
116→
117→    const identifier = payload.email || payload.sub;
118→    if (!identifier) {
119→      this.logger.warn('CipherBox JWT missing both email and sub claims');
120→      throw new UnauthorizedException('Invalid identity token: missing identifier');
121→    }
122→    const identifierHash = this.siweService.hashIdentifier(identifier);
123→    authMethod = await this.authMethodRepository.findOne({
124→      where: { userId: user.id, identifierHash },
125→    });
126→    if (!authMethod) {
127→      // Fallback: find any auth method for this user (identity controller should have created one)
128→      authMethod = await this.authMethodRepository.findOne({
129→        where: { userId: user.id },
130→      });
131→    }
132→    if (!authMethod) {
133→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
134→      // All logins go through loginType='corekit' now, but infer type from identifier format
135→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
136→      const display =
137→        inferredType === 'wallet'
138→          ? this.siweService.truncateWalletAddress(identifier)
139→          : this.siweService.truncateEmail(identifier);
140→      authMethod = await this.authMethodRepository.save({
141→        userId: user.id,
142→        type: inferredType,
143→        identifier: identifierHash,
144→        identifierHash,
145→        identifierDisplay: display,
146→      });
147→    }
148→
149→    // 4. Update last used timestamp
150→    authMethod.lastUsedAt = new Date();
151→    await this.authMethodRepository.save(authMethod);
152→
153→    // 5. Create tokens
154→    // REQUIRED_SHARE temp auth: issue scoped, non-refreshable tokens that only
155→    // grant access to the device-approval bulletin board. The new device will
156→    // do a second /auth/login with the real publicKey after key reconstruction.
157→    const isTempAuth = loginDto.publicKey.startsWith('pending-core-kit-') && !isNewUser;
158→    const tokens = await this.tokenService.createTokens(
159→      user.id,
160→      user.publicKey,
161→      isTempAuth ? { scope: ['device-approval'], skipRefreshToken: true } : undefined
162→    );
163→
164→    return {
165→      accessToken: tokens.accessToken,
166→      refreshToken: tokens.refreshToken,
167→      isNewUser,
168→    };
169→  }
