171→  /**
172→   * Verify a CipherBox-issued JWT for Core Kit login flow.
173→   * Since we are the identity provider, we verify against our own JWKS.
174→   */
175→  private async verifyCipherBoxJwt(
176→    idToken: string
177→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
178→    try {
179→      const jwksData = this.jwtIssuerService.getJwksData();
180→      const jwks = jose.createLocalJWKSet(jwksData);
181→      const { payload } = await jose.jwtVerify(idToken, jwks, {
182→        issuer: 'cipherbox',
183→        audience: 'web3auth',
184→        algorithms: ['RS256'],
185→      });
186→      return {
187→        sub: payload.sub,
188→        verifierId: payload.sub,
189→        email: payload.email as string | undefined,
190→      };
191→    } catch (error) {
192→      this.logger.warn(
193→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
194→      );
195→      throw new UnauthorizedException('Invalid CipherBox identity token');
196→    }
197→  }
